{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "투약 전 처방 확인에서 발견한 정보를 근거로 투약 진행 여부를 판단할 수 있는지 검증한다. 진통제 처방을 확인한 경험에서 투약을 보류해야 한다고 판단한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방을 투약 전에 확인한 상황이 드러난다.",
          "task": "확인한 처방에 따라 투약을 진행해도 되는지 판단해야 했음이 드러난다.",
          "action": "처방 용량을 대조한 정보와 확인되지 않은 사항을 근거로 투약 진행 여부를 판단한 내용을 설명한다.",
          "result": "투약을 보류해야 한다고 판단한 근거와 그 근거가 판단으로 이어진 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "당시 투약 진행 여부를 판단한 구체적인 근거",
          "처방 용량의 이상 여부를 확인하는 데 사용한 비교 정보",
          "확인되지 않은 처방을 그대로 수행하지 않기로 한 판단과 근거의 연결"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 진통제 처방을 확인하셨던데요, 당시 투약을 진행해도 되는지는 무엇을 근거로 판단하셨어요?",
      "answerTip": "당시 상황을 짧게 짚고 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "처방 용량을 어떤 정보와 대조했는지 구체적으로 설명한다.",
            "대조 결과에서 발견한 이상과 투약 보류 판단의 연결이 명확하며, 확인되지 않은 처방을 그대로 수행하지 않는 판단이 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "처방 용량이 의심스러워 투약을 보류했다고 설명하지만, 비교 정보나 판단 근거가 구체적이지 않다.",
            "처방 확인의 필요성은 드러나지만, 확인한 사실이 투약 진행 여부 판단으로 이어진 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "투약 진행 여부를 판단한 근거나 처방 용량을 비교한 정보를 제시하지 못한다.",
            "확인되지 않은 처방을 그대로 수행해도 된다고 설명하거나, 투약 판단과 무관한 내용만 답한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태 변화를 간호 기록에 정확하게 반영할 수 있는지 검증한다. 활력징후와 통증 관찰 기록에서 상태 변화를 분명하게 남기기 위해 주의를 기울인 부분에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 환자의 활력징후와 통증을 관찰하고 기록한 업무 상황이 드러난다.",
          "task": "관찰한 환자 상태 변화를 간호 기록에 정확하게 남겨야 했음이 드러난다.",
          "action": "상태 변화 기록에서 특히 신경 쓴 부분을 실제 관찰 내용과 기록 방식에 연결해 설명한다.",
          "result": "관찰한 사실과 환자 상태 변화가 기록에 분명하게 드러나도록 한 판단이 구체적으로 확인된다."
        },
        "expectedEvidence": [
          "환자 상태 변화 기록에서 가장 신경 쓴 구체적인 부분",
          "그 부분과 관련된 실제 활력징후 또는 통증 관찰 내용",
          "관찰한 사실과 변화가 기록에 정확히 드러나도록 한 기록 방식"
        ]
      },
      "question": "푸른결종합병원 정형외과 병동에서 활력징후와 통증 관찰 기록을 맡으셨던데요, 상태 변화 기록에서 가장 신경 쓰신 부분은 뭐였어요?",
      "answerTip": "기억나는 업무 장면을 떠올려 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "상태 변화 기록에서 가장 신경 쓴 부분을 실제 활력징후 또는 통증 관찰 내용으로 구체화한다.",
            "관찰한 사실과 변화가 정확하게 드러나도록 기록한 방식을 명확하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "상태 변화 기록에서 신경 쓴 부분은 제시하지만, 실제 관찰 내용과의 연결이 부족하다.",
            "정확한 기록을 위한 방식은 일부 설명하지만, 환자 상태 변화가 기록에 드러나는 방식은 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "기록에서 신경 쓴 부분을 제시하지 못하거나 정확히 기록했다는 일반적인 설명에 그친다.",
            "실제 관찰 내용과 기록 방식의 연결이 없거나, 관찰한 사실과 다른 내용을 기록하는 방식을 설명한다."
          ]
        }
      }
    }
  ]
}
